package run.ikaros.notes; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/private-notes/vaults/{vaultId}/tags") public class PrivateTagController{private final PrivateTagService service;public PrivateTagController(PrivateTagService s){service=s;}@PostMapping public Mono<PrivateTagView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody CreatePrivateTagRequest r){return service.create(a,vaultId,r);}@GetMapping public Flux<PrivateTagView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.list(a,vaultId);}}
